//! TCPIP32.DLL: the socket, resolver and network database calls of OS/2
//! TCP/IP 4.1 and later (4.4BSD structures: `sockaddr` with `sin_len`),
//! as FTP, TELNET, FINGER, the Toolkit samples and RXSOCK import them.
//! The work is done in `tcpipcore` over the kernel's sockets; every entry
//! point is `_System` and reached through the stack-aligning trampolines
//! of exports.rs (generated by tools/scripts/gen_pm_exports.py).

#![no_std]
#![no_main]
#![allow(non_snake_case, clippy::missing_safety_doc, clippy::too_many_arguments)]

extern crate alloc;
extern crate os2;

mod exports;

use core::ptr::{null, null_mut};

use tcpipcore::errno;
use tcpipcore::netdb::{self, Hostent, Netent, Protoent, Servent};
use tcpipcore::resolv;
use tcpipcore::sock::{self, Abi};
use tcpipcore::{cstr, inet};

const ABI: Abi = Abi::V41;

/// _DLL_InitTerm(hmod, flag).
#[unsafe(no_mangle)]
#[unsafe(link_section = ".text.start")]
pub extern "C" fn _start(_hmod: u32, _flag: u32) -> u32 {
    1
}

/// `__p_class_syms`, `__p_type_syms`: empty `struct res_sym` tables.
