#[unsafe(no_mangle)]
pub extern "C" fn inet_neta(net: u32, buf: *mut u8, size: u32) -> *mut u8 {
    // The network number (host order) as dotted parts without trailing
    // zero bytes ("0.0.0.0" for 0).
    let b = net.to_be_bytes();
    let first = b.iter().position(|&x| x != 0).unwrap_or(3);
    let parts: alloc::vec::Vec<alloc::string::String> = b[first..].iter().map(|x| alloc::format!("{x}")).collect();
    let v = if net == 0 { b"0.0.0.0".to_vec() } else { parts.join(".").into_bytes() };
    if unsafe { cstr::copy_out(&v, buf, size as usize) } { buf } else { null_mut() }
}
#[unsafe(no_mangle)]
pub extern "C" fn inet_pton(af: i32, src: *const u8, dst: *mut u8) -> i32 {
    if af != 2 {
        errno::set(errno::EAFNOSUPPORT);
        return -1;
    }
    let b = unsafe { cstr::bytes(src) };
    // Strict dotted quad for inet_pton.
    if b.iter().filter(|&&c| c == b'.').count() != 3 || !b.iter().all(|c| c.is_ascii_digit() || *c == b'.') {
        return 0;
    }
    match inet::aton(b) {
        Some(a) => {
            unsafe { core::ptr::copy_nonoverlapping(a.as_ptr(), dst, 4) };
            1
        }
        None => 0,
    }
}
#[unsafe(no_mangle)]
pub extern "C" fn inet_ntop(af: i32, src: *const u8, dst: *mut u8, size: u32) -> *const u8 {
    if af != 2 || src.is_null() {
        errno::set(errno::EAFNOSUPPORT);
        return null();
    }
    let mut a = [0u8; 4];
    unsafe { core::ptr::copy_nonoverlapping(src, a.as_mut_ptr(), 4) };
    if unsafe { cstr::copy_out(&inet::ntoa_vec(a), dst, size as usize) } {
        dst
    } else {
        errno::set(28);
        null()
    }
}
#[unsafe(no_mangle)]
pub extern "C" fn inet_net_ntop(af: i32, src: *const u8, bits: i32, dst: *mut u8, size: u32) -> *const u8 {
    if af != 2 || src.is_null() || !(0..=32).contains(&bits) {
        errno::set(errno::EINVAL);
        return null();
    }
    let mut a = [0u8; 4];
    unsafe { core::ptr::copy_nonoverlapping(src, a.as_mut_ptr(), 4) };
    let mut v = inet::ntoa_vec(a);
    v.push(b'/');
    v.extend_from_slice(alloc::format!("{bits}").as_bytes());
    if unsafe { cstr::copy_out(&v, dst, size as usize) } { dst } else { null() }
}
#[unsafe(no_mangle)]
pub extern "C" fn inet_net_pton(af: i32, src: *const u8, dst: *mut u8, size: u32) -> i32 {
    if af != 2 || size < 4 {
        errno::set(errno::EINVAL);
        return -1;
    }
    let b = unsafe { cstr::bytes(src) };
    let (a, bits) = match b.iter().position(|&c| c == b'/') {
        Some(i) => (&b[..i], core::str::from_utf8(&b[i + 1..]).ok().and_then(|x| x.parse::<i32>().ok())),
        None => (b, None),
    };
    match inet::aton(a) {
        Some(x) => {
            unsafe { core::ptr::copy_nonoverlapping(x.as_ptr(), dst, 4) };
            bits.unwrap_or(32).clamp(0, 32)
        }
        None => {
            errno::set(2);
            -1
        }
    }
}
