#[unsafe(no_mangle)]
pub extern "C" fn __dn_count_labels(name: *const u8) -> i32 {
    let b = unsafe { cstr::bytes(name) };
    let b = b.strip_suffix(b".").unwrap_or(b);
    if b.is_empty() { 0 } else { b.split(|&c| c == b'.').filter(|l| *l != b"*").count() as i32 }
}
